    TwistSquash::SquashKeyA(ANTARES_KEY_A_F_IceLaneA, ANTARES_KEY_A_F_IceLaneB, ANTARES_KEY_A_F_IceLaneC, ANTARES_KEY_A_F_IceLaneD, &(pWorkSpace->mKeyBoxA[5U][0]));

    // Key flow — A / G

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Antares_Arx::KEY_A_G_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Antares_Arx::KEY_A_G_B(PARAMS_SEED);

    KeyDiffuse_A_A_G(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Antares_Arx::KEY_A_G_C(PARAMS_SEED);

    //
    // src: [$water]
