    KeyDiffuse_B_A_G(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Antares_Arx::KEY_A_G_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ANTARES_KEY_A_G_IceLaneA, ANTARES_KEY_A_G_IceLaneB, ANTARES_KEY_A_G_IceLaneC, ANTARES_KEY_A_G_IceLaneD, &(pWorkSpace->mKeyBoxA[6U][0]));

    // Key flow — A / H

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Antares_Arx::KEY_A_H_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Antares_Arx::KEY_A_H_B(PARAMS_SEED);

    KeyDiffuse_A_A_H(pWorkSpace);

    //
    // src: [$rainbow]
