    TwistSquash::SquashKeyA(ANTARES_KEY_A_H_IceLaneA, ANTARES_KEY_A_H_IceLaneB, ANTARES_KEY_A_H_IceLaneC, ANTARES_KEY_A_H_IceLaneD, &(pWorkSpace->mKeyBoxA[7U][0]));

