    TwistSquash::SquashKeyA(ANTARES_KEY_B_B_IceLaneA, ANTARES_KEY_B_B_IceLaneB, ANTARES_KEY_B_B_IceLaneC, ANTARES_KEY_B_B_IceLaneD, &(pWorkSpace->mKeyBoxB[1U][0]));

    // Key flow — B / C

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Antares_Arx::KEY_B_C_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Antares_Arx::KEY_B_C_B(PARAMS_SEED);

    KeyDiffuse_A_B_C(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Antares_Arx::KEY_B_C_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Antares_Arx::KEY_B_C_D(PARAMS_SEED);

    KeyDiffuse_B_B_C(pWorkSpace);

    //
    // src: [$frost]
