    //
    TwistExpander_Antares_Arx::KEY_B_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ANTARES_KEY_B_C_IceLaneA, ANTARES_KEY_B_C_IceLaneB, ANTARES_KEY_B_C_IceLaneC, ANTARES_KEY_B_C_IceLaneD, &(pWorkSpace->mKeyBoxB[2U][0]));

    // Key flow — B / D

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Antares_Arx::KEY_B_D_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Antares_Arx::KEY_B_D_B(PARAMS_SEED);

    KeyDiffuse_A_B_D(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Antares_Arx::KEY_B_D_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Antares_Arx::KEY_B_D_D(PARAMS_SEED);

    KeyDiffuse_B_B_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Antares_Arx::KEY_B_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ANTARES_KEY_B_D_IceLaneA, ANTARES_KEY_B_D_IceLaneB, ANTARES_KEY_B_D_IceLaneC, ANTARES_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

    // Key flow — B / E

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Antares_Arx::KEY_B_E_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
