    KeyDiffuse_B_B_F(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Antares_Arx::KEY_B_F_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ANTARES_KEY_B_F_IceLaneA, ANTARES_KEY_B_F_IceLaneB, ANTARES_KEY_B_F_IceLaneC, ANTARES_KEY_B_F_IceLaneD, &(pWorkSpace->mKeyBoxB[5U][0]));

    // Key flow — B / G

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
