    TwistExpander_Antares_Arx::KEY_B_G_B(PARAMS_SEED);

    KeyDiffuse_A_B_G(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Antares_Arx::KEY_B_G_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Antares_Arx::KEY_B_G_D(PARAMS_SEED);

    KeyDiffuse_B_B_G(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Antares_Arx::KEY_B_G_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(ANTARES_KEY_B_G_IceLaneA, ANTARES_KEY_B_G_IceLaneB, ANTARES_KEY_B_G_IceLaneC, ANTARES_KEY_B_G_IceLaneD, &(pWorkSpace->mKeyBoxB[6U][0]));

    // Key flow — B / H

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
