    KeyDiffuse_A_B_H(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Antares_Arx::KEY_B_H_C(PARAMS_SEED);
    //
    // src: [$water]
